precondition:
const st = ARC.state;
const r1 = st.repos.find(function (r) { return r.id === 'r1'; });
const pr = st.prs.find(function (p) { return p.id === 'p1'; });
assert.ok(r1 && pr, 'the seeded acme-docs repository and its Open pull request exist');
assert.strictEqual(ARC.currentUser().username, 'alice-dev');
assert.strictEqual(pr.state, 'Open');
assert.strictEqual(pr.base, 'main');
assert.strictEqual(pr.compare, 'onboarding');
assert.strictEqual(pr.author, 'alice');
assert.notStrictEqual(ARC.currentUser().username, pr.author, 'the reviewer is not the PR author');
assert.strictEqual(pr.check.status, 'success', 'the check is successful for the eligible scenario');
assert.ok(st.protections.some(function (p) { return p.repoId === 'r1' && p.branch === 'main' && p.approval === true && p.check === true; }), 'main is protected with both rule toggles enabled');
assert.strictEqual((pr.reviews || []).length, 0, 'the reviewer has no decision yet');
assert.ok(mergeBlockers(pr, r1).length > 0, 'control: before the approval the eligible pull request is not mergeable');

check:
submitReview({ form: { decision: 'Approve', summary: '' } });
const r1 = ARC.state.repos.find(function (r) { return r.id === 'r1'; });
const pr = ARC.state.prs.find(function (p) { return p.id === 'p1'; });
assert.strictEqual(mergeBlockers(pr, r1).length, 0, 'with a valid non-author approval for the current compare commit and test: success, the eligible pull request must have no unmet merge condition');

