window.__before = JSON.stringify({ m: ARC.state.memberships, t: ARC.state.teamMembers || [], g: ARC.state.grants || [] });

precondition:
const st = ARC.state;
const owners = (st.memberships || []).filter(function (m) { return m.orgId === 'org1' && m.role === 'Owner'; });
assert.strictEqual(owners.length, 1, 'the scenario starts with exactly one Owner');
assert.strictEqual(owners[0].userId, 'u1');
assert.strictEqual(ARC.currentUser().username, 'alice-dev');
assert.ok((st.memberships || []).some(function (m) { return m.orgId === 'org1' && m.userId === 'u2'; }), 'other organization members exist independently of the Owner');
assert.ok((st.users || []).some(function (u) { return u.id === 'u1'; }), 'the member account exists before the removal attempt');

check:
confirmRemoveMember({ id: 'u1' });
const st = ARC.state;
assert.ok((st.memberships || []).some(function (m) { return m.orgId === 'org1' && m.userId === 'u1' && m.role === 'Owner'; }), 'removing the last Owner must be rejected and must keep the ownership relationship');
assert.strictEqual((st.memberships || []).filter(function (m) { return m.orgId === 'org1' && m.role === 'Owner'; }).length, 1, 'the organization must still have exactly one Owner');
assert.strictEqual(JSON.stringify({ m: st.memberships, t: st.teamMembers || [], g: st.grants || [] }), window.__before, 'a rejected removal must keep every organization relationship unchanged');
assert.ok((st.users || []).some(function (u) { return u.id === 'u1'; }), 'the account itself must not be deleted');

setup:
window.ARC = window.ARC || {};
ARC.esc = function (s) { return String(s == null ? '' : s); };
ARC.state = JSON.parse(JSON.stringify(window.SEED));
ARC.state.session = 'u1';
ARC.state.ui = ARC.state.ui || {};
ARC.state.ui.cmpBase = 'main';
ARC.state.ui.cmpCompare = 'onboarding';
ARC.save = function () {};
ARC.render = function () {};
ARC.navigate = function () {};
ARC.notify = function () {};
ARC.openDialog = function () {};
ARC.closeDialog = function () {};
ARC.openPopover = function () {};
ARC.closePopover = function () {};
ARC.dialogOpen = false;
ARC.uid = function (p) { return (p || 'x') + '-' + Math.random().toString(36).slice(2, 8); };
ARC.route = function () { return { name: 'r', params: ['alice-dev', 'acme-docs', 'pulls', 'compare'] }; };
ARC.currentUser = function () { return (ARC.state.users || []).find(function (u) { return u.id === ARC.state.session; }) || null; };

precondition:
const st = ARC.state;
const r1 = st.repos.find(function (r) { return r.id === 'r1'; });
assert.ok(r1, 'the seeded acme-docs repository exists');
assert.strictEqual(ARC.currentUser().username, 'alice-dev');
assert.strictEqual(st.ui.cmpBase, 'main');
assert.strictEqual(st.ui.cmpCompare, 'onboarding');
assert.ok(st.branches.some(function (b) { return b.repoId === 'r1' && b.name === 'main'; }));
assert.ok(st.branches.some(function (b) { return b.repoId === 'r1' && b.name === 'onboarding'; }));
const pair = st.prs.filter(function (p) { return p.repoId === 'r1' && p.base === 'main' && p.compare === 'onboarding' && (p.state === 'Open' || p.state === 'Draft'); });
assert.strictEqual(pair.length, 1, 'exactly one Open/Draft pull request already uses this base/compare pair');
assert.strictEqual(pair[0].state, 'Open');

check:
createPR({ form: { title: 'Second onboarding pull request', body: 'Duplicate of the open pull request.' }, el: { dataset: { draft: 'no' } } });
const st = ARC.state;
assert.strictEqual(st.prs.filter(function (p) { return p.title === 'Second onboarding pull request'; }).length, 0, 'reusing a Draft/Open base/compare pair must not create a second pull request');
assert.strictEqual(st.prs.filter(function (p) { return p.repoId === 'r1' && p.base === 'main' && p.compare === 'onboarding' && (p.state === 'Open' || p.state === 'Draft'); }).length, 1, 'exactly one Open/Draft pull request may exist for the pair');
st.ui.cmpBase = 'release';
st.ui.cmpCompare = 'feature-search';
createPR({ form: { title: 'Control pull request for an unused pair', body: '' }, el: { dataset: { draft: 'no' } } });
assert.strictEqual(st.prs.filter(function (p) { return p.title === 'Control pull request for an unused pair'; }).length, 1, 'control: the creation path does persist a pull request for an unused pair');
